INSERT INTO public.estoque_saldos (
  empresa_id, material_id, localizacao_id, quantidade
)
SELECT
  '72000000-0000-4000-8000-000000000001',
  material_id,
  '76000000-0000-4000-8000-000000000001',
  quantity
FROM (VALUES
  ('79000000-0000-4000-8000-000000000001'::uuid, 1),
  ('79000000-0000-4000-8000-000000000002'::uuid, 10),
  ('79000000-0000-4000-8000-000000000003'::uuid, 20),
  ('79000000-0000-4000-8000-000000000004'::uuid, 5),
  ('79000000-0000-4000-8000-000000000005'::uuid, 10),
  ('79000000-0000-4000-8000-000000000006'::uuid, 1),
